package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B9ResultLifecycleMysqlTest extends TestCase {
    private A1TestFixture f;private AgentStore store;private ControlledWriteService writes;private ObjectNode run,snapshot,args;private long book;
    protected void setUp() throws Exception {
        f=new A1TestFixture();store=new AgentStore(f.db);String sql=new String(Files.readAllBytes(Paths.get(System.getProperty("a1.module"),"sql/ai_agent_controlled_write_v2.sql")),StandardCharsets.UTF_8);f.db.execute(sql.replaceAll("(?m)^--[^\\r\\n]*","").trim());writes=new ControlledWriteService(store,f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());for(String field:new String[]{"enabled","b8EffectEnabled","b9ResultEnabled"})A1TestFixture.inject(writes,field,true);
        snapshot=(ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\",\"out\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"Name\"},\"1\":{\"v\":\"Amount\"}},\"1\":{\"0\":{\"v\":\"A\"},\"1\":{\"v\":7}},\"2\":{\"0\":{\"v\":\"B\"},\"1\":{\"v\":9}}}},\"out\":{\"id\":\"out\",\"name\":\"Result\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{}}}}");book=f.seed(snapshot.toString());ObjectNode ws=f.runs.workspace(book,1);run=obj().put("runId",UUID.randomUUID().toString()).put("userId",1L).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("revision",hash(snapshot)).put("activeSheetId","out").put("allowOverwrite",false).put("kind","CONTROLLED_WRITE").put("status","EXECUTING").put("version",0).put("eventSeq",0).put("fencingToken",1).put("planVersion",1).put("stepIndex",1).put("persistenceStatus","NOT_SAVED");for(String key:new String[]{"loadedRevision","expectedDraftVersion","expectedBranchVersion"})run.set(key,ws.path(key.equals("expectedDraftVersion")?"draftVersion":key.equals("expectedBranchVersion")?"branchVersion":key));run.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1:B3")));
        f.db.update("insert into ai_agent_run(run_id,user_id,workbook_id,branch_id,request_id,request_hash,status,state_json,row_version,updated_at,created_at) values(?,?,?,?,?,?,'EXECUTING',?,0,now(3),now(3))",text(run,"runId"),1,book,run.path("branchId").asLong(),UUID.randomUUID().toString(),hash(run),run.toString());f.db.update("insert into ai_agent_lease(workbook_id,run_id,fencing_token,expires_at) values(?,?,1,?)",book,text(run,"runId"),System.currentTimeMillis()+120000);
        ObjectNode read=obj().put("sheetId","s").put("range","A1:B3").put("headerRow",true).put("includeHidden",true).put("includeFiltered",true).put("formulaPolicy","reject"),ref=new AgentTools(store).execute(run,"build_dataset",read,snapshot);args=obj().put("sheetId","out").put("range","A1:B3").put("overwrite","empty-only");args.set("dataset",ref);
    }
    private ObjectNode prepare(){return f.tx.execute(tx->{f.guard.lock(book,1L);ObjectNode r=store.locked(text(run,"runId"));ObjectNode c=writes.prepareResultLocked(r,args);store.save(r);return c;});}
    private ObjectNode claim(){return writes.claim(text(run,"runId"),1,obj().put("transportVersion",2).put("clientId","b9-test").put("fencingToken",1));}
    private ObjectNode receipt(JsonNode m){ObjectNode r=obj().put("transportVersion",2).put("callId",text(m,"callId")).put("effectId",text(m,"effectId")).put("claimToken",text(m,"claimToken")).put("argsHash",text(m,"argsHash")).put("fencingToken",1).put("ok",true);ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode cell=obj().put("sheetId",text(c,"sheetId")).put("row",c.path("row").asInt()).put("column",c.path("column").asInt()).put("formula","");cell.set("value",c.path("value"));cells.add(cell);}r.set("cells",cells);return r;}
    private void reject(Runnable action){try{action.run();fail("untrusted lifecycle saved");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private void corruptSource(){String id=args.path("dataset").path("resultRef").asText();f.db.update("update ai_analysis_artifact set content_json=json_set(content_json,'$.data.rows[0].Amount',999) where artifact_id=?",id);}
    public void testSavedProvenanceAndIdenticalReceipt(){prepare();ObjectNode m=claim(),receipt=receipt(m),saved=writes.receipt(text(run,"runId"),1,receipt);assertEquals("COMPLETED",saved.path("status").asText());assertEquals(m.path("resultSource"),saved.path("lastControlledResult").path("executedChange").path("resultSource"));corruptSource();writes.receipt(text(run,"runId"),1,receipt);JsonNode actual=parse(String.valueOf(f.status(book).get("content")));assertEquals(snapshot.path("sheets").path("s"),actual.path("sheets").path("s"));assertEquals(9,actual.path("sheets").path("out").path("cellData").path("2").path("1").path("v").asInt());}
    public void testSourceChangedBeforeClaimRejects(){prepare();corruptSource();reject(()->claim());assertNull(f.status(book).get("workingState"));}
    public void testSourceChangedAfterClaimRejectsSave(){prepare();ObjectNode m=claim();corruptSource();reject(()->writes.receipt(text(run,"runId"),1,receipt(m)));assertNull(f.status(book).get("workingState"));}
    public void testGateClosedAfterClaimRejectsSave() throws Exception {prepare();ObjectNode m=claim();A1TestFixture.inject(writes,"b9ResultEnabled",false);reject(()->writes.receipt(text(run,"runId"),1,receipt(m)));assertNull(f.status(book).get("workingState"));}
    public void testBranchRevocationAfterClaimRejectsSave(){prepare();ObjectNode m=claim();f.db.update("update ai_workbook_branch set status='archived' where branch_id=?",run.path("branchId").asLong());reject(()->writes.receipt(text(run,"runId"),1,receipt(m)));assertEquals(0,f.db.queryForObject("select count(*) from ai_workbook_working_state where workbook_id=?",Integer.class,book).intValue());}
    public void testEffectIdentityBindsFrozenSource(){ObjectNode call=prepare(),manifest=(ObjectNode)call.path("manifest"),forged=manifest.deepCopy();((ObjectNode)forged.path("resultSource")).put("dataDigest","forged");assertFalse(StableEffectLedger.identity(manifest).path("argsHash").equals(StableEffectLedger.identity(forged).path("argsHash")));claim();assertFalse(claim().path("replayAllowed").asBoolean());}
}
